/**
 * SubProcessAdapter — TD-A2 implementation.
 *
 * Spawns the Claude executor binary as a child process inside the same
 * container. Serializes ExecutorInput into environment variables, waits for
 * child exit, reads and validates result.json from resultPath.
 *
 * This is the default ExecutorAdapter wired in main.ts. Future adapters
 * (DockerRunAdapter, K8sJobAdapter, QueueProducerAdapter) would implement
 * the same interface without touching orchestrator-core code.
 */

import { spawn } from "node:child_process";
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import type { ExecutorAdapter, ExecutorInput, ExecutorResult } from "@workflow/runtime-abi";
import { validateResult } from "@workflow/runtime-abi";

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

export interface SubProcessAdapterOpts {
  /**
   * Path to the executor entrypoint JS file.
   * Defaults to the sibling executor binary baked into the same container.
   */
  executorBinPath?: string;
  /**
   * Maximum wall-clock milliseconds to wait for the executor to exit.
   * Defaults to 2 hours (7_200_000 ms).
   */
  timeoutMs?: number;
  /**
   * Extra environment variables to pass to the executor process beyond the
   * formal ABI env vars. Used for day-1 single-container extras like
   * WORKSPACE_ROOT, GIT_AUTHOR_EMAIL, WORKFLOW_LOCAL_PATH, etc.
   */
  extraEnv?: NodeJS.ProcessEnv;
}

export class SubProcessAdapter implements ExecutorAdapter {
  private readonly executorBinPath: string;
  private readonly timeoutMs: number;
  private readonly extraEnv: NodeJS.ProcessEnv;

  constructor(opts: SubProcessAdapterOpts = {}) {
    this.executorBinPath =
      opts.executorBinPath ??
      join(
        // The executor binary is baked into the Docker image at /workflow/...
        // WORKFLOW_LOCAL_PATH points to the git-clone volume (/agent/workflow) and
        // must NOT be used here — those are two separate paths inside the container.
        process.env.EXECUTOR_BIN_PREFIX ?? "/workflow",
        "runtime",
        "executors",
        "claude",
        "dist",
        "index.js",
      );
    this.timeoutMs = opts.timeoutMs ?? 7_200_000;
    this.extraEnv = opts.extraEnv ?? {};
  }

  async run(input: ExecutorInput): Promise<ExecutorResult> {
    const {
      taskId,
      featureId,
      workspaceId,
      taskRepoUrl,
      taskRepoBranch,
      taskRepoPath,
      briefingPath,
      resultPath,
      budgetTokens,
      sshKeyPath,
      githubToken,
    } = input;

    const childEnv: NodeJS.ProcessEnv = {
      ...process.env,
      ...this.extraEnv,
      // Formal ABI env vars
      TASK_ID: taskId,
      FEATURE_ID: featureId,
      WORKSPACE_ID: workspaceId,
      TASK_REPO_URL: taskRepoUrl,
      TASK_REPO_BRANCH: taskRepoBranch,
      TASK_REPO_PATH: taskRepoPath,
      BRIEFING_PATH: briefingPath,
      RESULT_PATH: resultPath,
      GITHUB_TOKEN: githubToken,
      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
    };

    emit({
      type: "executor_spawn",
      task_id: taskId,
      feature_id: featureId,
      bin: this.executorBinPath,
    });

    const { status, error } = await new Promise<{
      status: number | null;
      signal: string | null;
      error?: Error;
    }>((resolve) => {
      const child = spawn("node", [this.executorBinPath], {
        env: childEnv,
        stdio: "inherit",
      });

      let watchdog: ReturnType<typeof setTimeout> | null = null;
      watchdog = setTimeout(() => {
        if (!child.killed) {
          emit({ type: "executor_timeout", task_id: taskId, feature_id: featureId, timeout_ms: this.timeoutMs });
          child.kill("SIGTERM");
        }
      }, this.timeoutMs);

      child.on("error", (err: Error) => {
        if (watchdog !== null) clearTimeout(watchdog);
        resolve({ status: null, signal: null, error: err });
      });

      child.on("close", (code: number | null, signal: string | null) => {
        if (watchdog !== null) clearTimeout(watchdog);
        resolve({ status: code, signal });
      });
    });

    emit({
      type: "executor_exit",
      task_id: taskId,
      feature_id: featureId,
      exit_code: status,
    });

    if (error) {
      return {
        terminal_status: "failed",
        blocked_reason: `executor_spawn_error: ${error.message}`,
      };
    }

    // ── Read result.json ──────────────────────────────────────────────────────
    if (!existsSync(resultPath)) {
      const reason =
        status !== 0 && status !== null
          ? `executor_crashed (exit ${status})`
          : "no_result_file";
      return {
        terminal_status: "failed",
        blocked_reason: reason,
      };
    }

    let raw: unknown;
    try {
      raw = JSON.parse(readFileSync(resultPath, "utf-8"));
    } catch (e) {
      return {
        terminal_status: "failed",
        blocked_reason: `result_parse_error: ${String(e)}`,
      };
    }

    const validation = validateResult(raw);
    if (!validation.valid) {
      return {
        terminal_status: "failed",
        blocked_reason: `result_schema_invalid: ${validation.errors?.join("; ")}`,
      };
    }

    return raw as ExecutorResult;
  }
}

