/**
 * local-subprocess profile factory.
 *
 * Bundles the Wave-2 adapter set into a RuntimePorts instance for the
 * single-container, single-process topology: orchestrator and executor
 * run as child processes inside the same image.
 *
 * Adapter set:
 *   ExecutorPort         → SubProcessAdapterW2  (blocks in Wave 2; async in Wave 3)
 *   CompletionBrokerPort → NullBrokerAdapter     (no-op until Wave 3 / T3)
 *   BriefingTransport    → LocalFileBriefingAdapter
 *   WorkflowState        → GitWorkflowStateAdapter
 *   Credential           → EnvCredentialAdapter
 *   WorkspacePull        → GitClonePullAdapter
 *   EventEmitter         → StdoutJsonEmitter
 *   Scheduler            → SimpleSleepScheduler
 *   Clock                → RealClock
 */

import type { RuntimePorts } from "../runtime-ports.js";
import { SubProcessAdapterW2, type SubProcessAdapterOpts } from "../adapters/subprocess-adapter.js";
import { NullBrokerAdapter } from "../adapters/null-broker.js";
import { LocalFileBriefingAdapter } from "../adapters/local-file-briefing.js";
import { GitWorkflowStateAdapter } from "../adapters/git-workflow-state.js";
import { EnvCredentialAdapter } from "../adapters/env-credential.js";
import { GitClonePullAdapter } from "../adapters/git-clone-pull.js";
import { StdoutJsonEmitter } from "../adapters/stdout-json-emitter.js";
import { SimpleSleepScheduler } from "../adapters/simple-sleep-scheduler.js";
import { RealClock } from "../adapters/real-clock.js";

export interface LocalSubprocessProfileOpts {
  /** Options forwarded to SubProcessAdapterW2. */
  executor?: SubProcessAdapterOpts;
  /** Git identity for WorkflowStatePort operations. */
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/**
 * Create a RuntimePorts bundle wired for the local-subprocess profile.
 *
 * Called once at orchestrator startup; the returned bundle is passed to
 * every concern that needs port access.
 */
export function createLocalSubprocessProfile(
  opts: LocalSubprocessProfileOpts,
): RuntimePorts {
  return {
    executor: new SubProcessAdapterW2(opts.executor),
    broker: new NullBrokerAdapter(),
    briefing: new LocalFileBriefingAdapter(),
    workflowState: new GitWorkflowStateAdapter({
      gitAuthorEmail: opts.gitAuthorEmail,
      gitAuthorName: opts.gitAuthorName,
      sshKeyPath: opts.sshKeyPath,
    }),
    credential: new EnvCredentialAdapter(),
    workspacePull: new GitClonePullAdapter(),
    emitter: new StdoutJsonEmitter(),
    scheduler: new SimpleSleepScheduler(),
    clock: new RealClock(),
  };
}

