describe("EnvCredentialAdapter", () => {
  it("reads GITHUB_TOKEN from env", async () => {
    const adapter = new EnvCredentialAdapter({ env: { GITHUB_TOKEN: "ghp_test_token" } });
    expect(await adapter.getGitHubToken()).toBe("ghp_test_token");
  });

  it("returns empty string when GITHUB_TOKEN is absent", async () => {
    const adapter = new EnvCredentialAdapter({ env: {} });
    expect(await adapter.getGitHubToken()).toBe("");
  });

  it("reads SSH_KEY_PATH from env", async () => {
    const adapter = new EnvCredentialAdapter({ env: { SSH_KEY_PATH: "/home/user/.ssh/id_rsa" } });
    expect(await adapter.getSshKeyPath()).toBe("/home/user/.ssh/id_rsa");
  });

  it("returns empty string when SSH_KEY_PATH is absent", async () => {
    const adapter = new EnvCredentialAdapter({ env: {} });
    expect(await adapter.getSshKeyPath()).toBe("");
  });

  it("ignores tenantId (single-tenant Wave 2)", async () => {
    const adapter = new EnvCredentialAdapter({ env: { GITHUB_TOKEN: "token_a" } });
    expect(await adapter.getGitHubToken("tenant_X")).toBe("token_a");
  });
});

