/**
 * EnvCredentialAdapter — CredentialPort adapter.
 *
 * Reads credentials from process.env. Suitable for all local profiles.
 * The tenantId parameter is accepted but ignored in this feature — the
 * call-site shape is ready for future multi-tenant use without modifying
 * every call site.
 */

import type { CredentialPort } from "@workflow/runtime-abi";

export interface EnvCredentialAdapterOpts {
  /** Override the env object (defaults to process.env). Useful in tests. */
  env?: NodeJS.ProcessEnv;
}

export class EnvCredentialAdapter implements CredentialPort {
  private readonly env: NodeJS.ProcessEnv;

  constructor(opts: EnvCredentialAdapterOpts = {}) {
    this.env = opts.env ?? process.env;
  }

  async getGitHubToken(_tenantId?: string): Promise<string> {
    return this.env.GITHUB_TOKEN ?? "";
  }

  async getSshKeyPath(_tenantId?: string): Promise<string> {
    return (
      this.env.SSH_KEY_PATH ??
      this.env.SSH_PRIVATE_KEY_PATH ??
      ""
    );
  }
}

