// ── 7. SubProcessAdapterW2 ────────────────────────────────────────────────────

describe("SubProcessAdapterW2", () => {
  it("submit() + readResult() returns the executor result", async () => {
    const tmpDir = mkdtempSync(join(tmpdir(), "subprocess-w2-"));
    const resultPath = join(tmpDir, "result.json");
    const stubPath = join(tmpDir, "stub.js");

    // Write a stub that writes a valid result.json and exits 0.
    const { writeFileSync } = await import("node:fs");
    writeFileSync(
      stubPath,
      [
        `const fs = require("node:fs");`,
        `const resultPath = process.env.RESULT_PATH;`,
        `fs.writeFileSync(resultPath, JSON.stringify({ terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" }));`,
        `process.exit(0);`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapterW2({
      executorBinPath: stubPath,
      timeoutMs: 5_000,
      extraEnv: { RESULT_PATH: resultPath },
    });

    const handle = await adapter.submit({
      taskId: "T1",
      featureId: "f1",
      workspaceId: "ws",
      taskRepoUrl: "git@github.com:org/repo.git",
      taskRepoBranch: "feature/f1-T1",
      taskRepoPath: tmpDir,
      briefingPath: join(tmpDir, "briefing.md"),
      resultPath,
      sshKeyPath: "",
      githubToken: "",
      callbackUrl: "",
      nonce: "",
    });

    expect(typeof handle).toBe("string");
    expect(handle.length).toBeGreaterThan(0);

    const result = await adapter.readResult(handle);
    expect(result.terminal_status).toBe("in_review");
    expect(result.pr_url).toBe("https://github.com/org/repo/pull/1");

    rmSync(tmpDir, { recursive: true, force: true });
  }, 15_000);

  it("readResult() returns failed with handle_not_found for unknown handle", async () => {
    const adapter = new SubProcessAdapterW2();
    const result = await adapter.readResult("unknown-handle-xyz");
    expect(result.terminal_status).toBe("failed");
    expect(result.blocked_reason).toBe("handle_not_found");
  });

  it("readResult() removes the result from the map after retrieval", async () => {
    const tmpDir = mkdtempSync(join(tmpdir(), "subprocess-w2-remove-"));
    const resultPath = join(tmpDir, "result.json");
    const stubPath = join(tmpDir, "stub.js");

    const { writeFileSync } = await import("node:fs");
    writeFileSync(
      stubPath,
      [
        `const fs = require("node:fs");`,
        `fs.writeFileSync(process.env.RESULT_PATH, JSON.stringify({ terminal_status: "in_review" }));`,
        `process.exit(0);`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapterW2({
      executorBinPath: stubPath,
      timeoutMs: 5_000,
      extraEnv: { RESULT_PATH: resultPath },
    });

    const handle = await adapter.submit({
      taskId: "T1", featureId: "f1", workspaceId: "ws",
      taskRepoUrl: "", taskRepoBranch: "", taskRepoPath: tmpDir,
      briefingPath: "", resultPath, sshKeyPath: "", githubToken: "",
      callbackUrl: "", nonce: "",
    });

    await adapter.readResult(handle); // first read — succeeds
    const second = await adapter.readResult(handle); // second read — handle gone
    expect(second.terminal_status).toBe("failed");
    expect(second.blocked_reason).toBe("handle_not_found");

    rmSync(tmpDir, { recursive: true, force: true });
  }, 15_000);
});

// ── 8. local-subprocess profile factory ──────────────────────────────────────

describe("createLocalSubprocessProfile", () => {
  it("returns a RuntimePorts bundle with all nine ports populated", () => {
    const profile = createLocalSubprocessProfile({
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Agent",
      sshKeyPath: undefined,
    });

    expect(profile.executor).toBeDefined();
    expect(profile.broker).toBeDefined();
    expect(profile.briefing).toBeDefined();
    expect(profile.workflowState).toBeDefined();
    expect(profile.credential).toBeDefined();
    expect(profile.workspacePull).toBeDefined();
    expect(profile.emitter).toBeDefined();
    expect(profile.scheduler).toBeDefined();
    expect(profile.clock).toBeDefined();
  });

  it("credential adapter reads GITHUB_TOKEN from process.env", async () => {
    const original = process.env.GITHUB_TOKEN;
    process.env.GITHUB_TOKEN = "test_token_from_profile";

    const profile = createLocalSubprocessProfile({ gitAuthorEmail: "a@test.com" });
    const token = await profile.credential.getGitHubToken();
    expect(token).toBe("test_token_from_profile");

    if (original !== undefined) {
      process.env.GITHUB_TOKEN = original;
    } else {
      delete process.env.GITHUB_TOKEN;
    }
  });
});

